export type Role = "host" | "supply_lead" | "chef" | "server";

/** Categories a mid-shift standing correction can carry. Matches trace `correctionCategory`. */
export type CorrectionCategory = "safety" | "priority" | "quality" | "pace";

/**
 * A player correction that stays in force until it is explicitly lifted.
