/**
 * Standing corrections currently addressed to `role`, in the order they
 * were issued. Lifted corrections are omitted.
 */
directivesFor(role: Role | "expediter"): StandingDirective[] {
  const canonical: Role = role === "expediter" ? "supply_lead" : role;
  return this.activeDirectives().filter((directive) => directive.targetRoles.includes(canonical));
}

/** Every standing correction still in force, in issue order. */
activeDirectives(): StandingDirective[] {
  return this.standingDirectives
    .filter((directive) => !directive.lifted)
    .map((directive) => this.cloneDirective(directive));
}

/**
 * Lift a standing correction so it no longer binds later turns. Returns
 * false if the id is unknown or already lifted.
 */
liftDirective(id: string): boolean {
  const directive = this.standingDirectives.find((candidate) => candidate.id === id);
  if (!directive || directive.lifted) return false;
  directive.lifted = true;
  if (directive.category === "pace" && !this.hasActiveHoldDoorCorrection()) {
    this.currentState.seatingHeld = false;
  }
  return true;
}

/**
 * Scope-control report for the warming-shelf complication. `outcome` is
 * `"pending"` until the trigger fires, `"scope_held"` from that instant
 * (even with no decisions yet), and `"over_generalized"` only once a
 * false positive has been recorded.
 */
probeReport(): ProbeReport {
  const decisions = this.probeDecisions.map((decision) => ({
    ...decision,
    ...(decision.arguments ? { arguments: { ...decision.arguments } } : {}),
  }));
  const falsePositives = decisions.filter((decision) => decision.falsePositive).length;
  const outcome =
    this.probeTriggeredAtTick === null ? "pending" : falsePositives > 0 ? "over_generalized" : "scope_held";
  return { outcome, falsePositives, decisions };
}

