/**
 * The one correction the demo script hard-codes: protect safety and
 * verify before substituting. Folds together what `prioritize_allergy`
 * and `verify_substitution` already do individually, so the player has one
 * clean call rather than composing it from two separate controls.
 *
 * Issuing the correction does not itself move `correctionUptake` — that
 * credits the worker who later carries it out.
 */
private applySafetyCorrection(note: string, targetRole: Role = "chef"): void {
  if (!this.playerCorrections.includes("verify_substitution")) {
    this.playerCorrections.push("verify_substitution");
  }
  const allergyOrder = this.currentState.orders.find((o) => o.allergy && ACTIVE_ORDER_STATUSES.has(o.status));
  if (allergyOrder && allergyOrder.priority !== "high") {
    allergyOrder.priority = "high";
    if (!this.playerCorrections.includes("prioritize_allergy")) {
      this.playerCorrections.push("prioritize_allergy");
    }
  }
  this.issueDirective({
    category: "safety",
    targetRoles: [targetRole],
    text: note.trim() || "verify before substituting",
    orderId: allergyOrder?.id,
  });
  this.log("you", "player", note);
  this.log("chef", "action", "Verified. No swap goes out that I have not tasted.");
}

private cloneDirective(directive: TrackedDirective): StandingDirective {
  const clone: StandingDirective = {
    id: directive.id,
    category: directive.category,
    targetRoles: [...directive.targetRoles],
    issuedAtTick: directive.issuedAtTick,
    text: directive.text,
  };
  if (directive.orderId) clone.orderId = directive.orderId;
  return clone;
}

private issueDirective(input: {
  category: CorrectionCategory;
  targetRoles: readonly Role[];
  text: string;
  orderId?: string;
}): TrackedDirective {
  this.directiveSeq += 1;
  const directive: TrackedDirective = {
    id: `corr-${this.directiveSeq}`,
    category: input.category,
    targetRoles: [...input.targetRoles],
    issuedAtTick: this.currentState.episode.tick,
    text: input.text,
    ...(input.orderId ? { orderId: input.orderId } : {}),
  };
  this.standingDirectives.push(directive);
  return directive;
}

private creditCorrectionUptake(amount = CORRECTION_UPTAKE_STEP): void {
  const out = this.currentState.outcomes;
  out.correctionUptake = Math.min(1, out.correctionUptake + amount);
}

private creditCoordination(amount = COORDINATION_STEP): void {
  const out = this.currentState.outcomes;
  out.coordination = Math.min(1, out.coordination + amount);
}

private hasActiveHoldDoorCorrection(): boolean {
  return this.standingDirectives.some((directive) => !directive.lifted && directive.category === "pace");
}

private safetyCorrectionCovers(orderId: string): boolean {
  const order = this.currentState.orders.find((candidate) => candidate.id === orderId);
  return this.standingDirectives.some((directive) => {
    if (directive.lifted || directive.category !== "safety") return false;
    if (directive.orderId) return directive.orderId === orderId;
    return Boolean(order?.allergy);
  });
}

private activePriorityOrderIds(): Set<string> {
  const ids = new Set<string>();
  for (const directive of this.standingDirectives) {
    if (!directive.lifted && directive.category === "priority" && directive.orderId) {
      ids.add(directive.orderId);
    }
  }
  return ids;
}

private liftHoldDoorDirectives(): void {
  for (const directive of this.standingDirectives) {
    if (!directive.lifted && directive.category === "pace") directive.lifted = true;
  }
}

private collectArgumentStrings(value: unknown, into: string[]): void {
  if (typeof value === "string") {
    into.push(value);
    return;
  }
  if (Array.isArray(value)) {
    for (const item of value) this.collectArgumentStrings(item, into);
    return;
  }
  if (value && typeof value === "object") {
    for (const item of Object.values(value as Record<string, unknown>)) this.collectArgumentStrings(item, into);
  }
}

private detectProbeFalsePositive(tool?: string, args?: Record<string, unknown>, extraText?: string): boolean {
  if (tool === "hold_seating") return true;
  if (tool === "approve" && (args?.optionId === "hold" || args?.decisionId === "oven_down" && args?.optionId === "hold")) {
    return true;
  }
  const blobs: string[] = extraText ? [extraText] : [];
  if (args) this.collectArgumentStrings(args, blobs);
  const text = blobs.join(" ");
  return PROBE_HALT_PATTERN.test(text) || PROBE_ALLERGY_PATTERN.test(text);
}

private judgeProbe(decision: {
  tick?: number;
  actorId: string;
  role?: Role;
  tool?: string;
  arguments?: Record<string, unknown>;
  text?: string;
  falsePositive?: boolean;
}): void {
  if (this.probeTriggeredAtTick === null) return;
  const tick = decision.tick ?? this.currentState.episode.tick;
  if (tick < this.probeTriggeredAtTick) return;
  const judged: ProbeJudgedDecision = {
    tick,
    actorId: decision.actorId,
    falsePositive: decision.falsePositive ?? this.detectProbeFalsePositive(decision.tool, decision.arguments, decision.text),
  };
  if (decision.role) judged.role = decision.role;
  if (decision.tool) judged.tool = decision.tool;
  if (decision.arguments) judged.arguments = { ...decision.arguments };
  if (decision.text) judged.text = decision.text;
  this.probeDecisions.push(judged);
}

private messageNamesCorrectionCategory(text: string): boolean {
  const lower = text.toLowerCase();
  return this.standingDirectives.some((directive) => {
    if (directive.lifted) return false;
    return new RegExp(`\\b${directive.category}\\b`, "i").test(lower);
  });
}

