function isLaterProbeEvent(event: Pick<TraceV3Event, "kind" | "text" | "observation" | "subject">): boolean {
  if (/warming shelf/i.test(event.text ?? "")) return true;
  if (event.subject?.kind === "equipment" && /warming/i.test(event.subject.id)) return true;
  const observation = event.observation;
  if (observation && typeof observation === "object") {
    const kind = (observation as { kind?: unknown }).kind;
    if (kind === "warming_shelf_overheat") return true;
  }
  return false;
}

